import{_ as a,o as t,c as i,aw as l}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Уровни тестирования","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/testing/testing/theory/levels.md","filePath":"wiki/dev-commit/testing/testing/theory/levels.md"}'),r={name:"wiki/dev-commit/testing/testing/theory/levels.md"};function o(n,e,s,h,d,_){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="уровни-тестирования" tabindex="-1">Уровни тестирования <a class="header-anchor" href="#уровни-тестирования" aria-label="Permalink to &quot;Уровни тестирования&quot;">​</a></h1><h3 id="_1-тестирование-компонентов" tabindex="-1">1. Тестирование компонентов <a class="header-anchor" href="#_1-тестирование-компонентов" aria-label="Permalink to &quot;1. Тестирование компонентов&quot;">​</a></h3><ul><li>Тестируется минимально возможный для тестирования компонент, например, отдельный класс или функция. Часто тестирование компонентов осуществляется разработчиками программного обеспечения</li></ul><h3 id="_2-интеграционное-тестирование" tabindex="-1">2. Интеграционное тестирование <a class="header-anchor" href="#_2-интеграционное-тестирование" aria-label="Permalink to &quot;2. Интеграционное тестирование&quot;">​</a></h3><ul><li>Тестируются интерфейсы между компонентами, подсистемами или системами. При наличии резерва времени на данной стадии тестирование ведётся итерационно, с постепенным подключением последующих подсистем</li></ul><h3 id="_3-системное-тестирование" tabindex="-1">3. Системное тестирование <a class="header-anchor" href="#_3-системное-тестирование" aria-label="Permalink to &quot;3. Системное тестирование&quot;">​</a></h3><ul><li>Тестируется интегрированная система на её соответствие требованиям</li></ul><h4 id="классификация" tabindex="-1">Классификация <a class="header-anchor" href="#классификация" aria-label="Permalink to &quot;Классификация&quot;">​</a></h4><ul><li>Альфа-тестирование имитация реальной работы с системой. Чаще всего альфа-тестирование проводится на ранней стадии разработки продукта, но в некоторых случаях может применяться для законченного продукта в качестве внутреннего приёмочного тестирования. Иногда альфа-тестирование выполняется под отладчиком или с использованием окружения, которое помогает быстро выявлять найденные ошибки. Обнаруженные ошибки могут быть переданы тестировщикам для дополнительного исследования в окружении, подобном тому, в котором будет использоваться программа</li><li>Бета-тестирование в некоторых случаях выполняется распространение предварительной версии (в случае проприетарного программного обеспечения иногда с ограничениями по функциональности или времени работы) для некоторой большей группы лиц с тем, чтобы убедиться, что продукт содержит достаточно мало ошибок. Иногда бета-тестирование выполняется для того, чтобы получить обратную связь о продукте от его будущих пользователей</li></ul>',9)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
